/**
 * SQL corpus from the 0.1.0 research harness: realistic model-generated
 * read-only queries per dialect, and dangerous queries a SELECT-only validator
 * must reject. 159 valid queries, 11 extra valid edge cases and
 * 39 dangerous ones.
 */

export type CorpusDialect = 'postgres' | 'mysql' | 'sqlite' | 'mssql';

